package com.shubham.salarytracker;
import android.content.Context;
import android.content.SharedPreferences;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Immutable ancestry snapshots. The UI validates incoming/merged ledgers before applying. */
final class DriveSync {
 static final Object LOCK=new Object();private static final Object NETWORK_LOCK=new Object();
 static String ns(String email){return DriveBackup.hash(email.toLowerCase(java.util.Locale.ROOT));}
 static String current(Context c){return c.getSharedPreferences("drive",0).getString("email","");}
 static AtomicFile pending(Context c,String email){return new AtomicFile(new File(c.getFilesDir(),"sync-pending-"+ns(email)+".json"));}
 static void write(AtomicFile file,String text)throws Exception{FileOutputStream out=null;try{out=file.startWrite();out.write(text.getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 static void status(Context c,String email,String message){c.getSharedPreferences("drive",0).edit().putString("status-"+ns(email),message).apply();}
 static String readPending(Context c){synchronized(LOCK){String email=current(c);if(email.isEmpty())return "";try{return new String(pending(c,email).readFully(),StandardCharsets.UTF_8);}catch(Exception e){return "";}}}
 static boolean apply(Context c,String ticket,String data){synchronized(LOCK){String email=current(c);if(email.isEmpty())return false;try(LedgerStore store=new LedgerStore(c,ns(email))){JSONObject p=new JSONObject(readPending(c));if(!ticket.equals(p.getString("ticket"))||!SyncPolicy.digest(store.load()).equals(p.getString("expected"))||!SyncPolicy.digest(data).equals(SyncPolicy.digest(p.getJSONObject("data").put("version",6).toString())))return false;write(new AtomicFile(new File(c.getFilesDir(),"before-restore"+ns(email)+".json")),store.load());store.save(data);c.getSharedPreferences("drive",0).edit().putString("base-"+ns(email),p.getString("remoteId")).putString("baseHash-"+ns(email),p.getString("remoteHash")).remove("conflict-"+ns(email)).apply();pending(c,email).delete();status(c,email,"Synced. Your previous local version is kept as a recovery copy.");return true;}catch(Exception e){return false;}}}
 static void cycle(Context c,String email,String token,boolean keepLocal)throws Exception{synchronized(NETWORK_LOCK){if(!email.equals(current(c)))return;JSONObject user=new JSONObject(DriveBackup.request("GET","https://www.googleapis.com/oauth2/v3/userinfo",token,null,null));if(!email.equalsIgnoreCase(user.getString("email")))throw new IOException("Wrong Google account");JSONArray all=list(c,token),heads=SyncPolicy.heads(all);SharedPreferences prefs=c.getSharedPreferences("drive",0);String namespace=ns(email),data,localHash,base=prefs.getString("base-"+namespace,""),baseHash=prefs.getString("baseHash-"+namespace,"");synchronized(LOCK){if(!email.equals(current(c)))return;try(LedgerStore store=new LedgerStore(c,namespace)){data=store.load();}if(data.isEmpty())return;localHash=SyncPolicy.digest(data);}
 String action=keepLocal?"upload":SyncPolicy.decide(localHash,baseHash,base,heads,SyncPolicy.empty(new JSONObject(data)));
 if(action.equals("conflict")){prefs.edit().putString("conflict-"+namespace,heads.toString()).apply();status(c,email,"Changes overlap across devices. Open Drive sync to review versions; nothing was overwritten.");return;}
 if(action.equals("current")){status(c,email,"Up to date · "+new java.text.SimpleDateFormat("dd MMM HH:mm",java.util.Locale.getDefault()).format(new java.util.Date()));return;}
 if(action.equals("upload")){JSONArray parents=new JSONArray();for(int i=0;i<heads.length();i++)parents.put(heads.getJSONObject(i).getString("id"));JSONObject meta=new JSONObject().put("name","Salary-sync-"+System.currentTimeMillis()+".json").put("parents",new JSONArray().put("appDataFolder")).put("description",new JSONObject().put("salarySync",1).put("parents",parents).toString());String boundary="Salary"+System.nanoTime(),body="--"+boundary+"\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n"+meta+"\r\n--"+boundary+"\r\nContent-Type: application/json\r\n\r\n"+data+"\r\n--"+boundary+"--";if(!email.equals(current(c)))return;JSONObject result=new JSONObject(DriveBackup.request("POST","https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id",token,body,"multipart/related; boundary="+boundary));synchronized(LOCK){prefs.edit().putString("base-"+namespace,result.getString("id")).putString("baseHash-"+namespace,localHash).remove("conflict-"+namespace).apply();pending(c,email).delete();}status(c,email,"Backed up · "+new java.text.SimpleDateFormat("dd MMM HH:mm",java.util.Locale.getDefault()).format(new java.util.Date()));return;}
 String id=heads.getJSONObject(0).getString("id"),remote=download(token,id),remoteHash=SyncPolicy.digest(remote),candidate=remote;
 if(action.equals("merge")){try{candidate=SyncPolicy.merge(new JSONObject(download(token,base)),new JSONObject(data),new JSONObject(remote)).toString();}catch(Exception e){prefs.edit().putString("conflict-"+namespace,heads.toString()).apply();status(c,email,"Both devices edited the same item. Review versions in Drive sync.");return;}}
 synchronized(LOCK){if(!email.equals(current(c)))return;try(LedgerStore store=new LedgerStore(c,namespace)){if(!SyncPolicy.digest(store.load()).equals(localHash))return;}write(pending(c,email),new JSONObject().put("ticket",java.util.UUID.randomUUID().toString()).put("expected",localHash).put("remoteId",id).put("remoteHash",remoteHash).put("data",new JSONObject(candidate)).toString());}status(c,email,"Downloaded changes ready. They apply after validation when the app is open and no form is being edited.");}}
 static JSONArray list(Context c,String token)throws Exception{JSONArray files=new JSONArray();String page="";do{String url="https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&q=trashed%3Dfalse&fields=nextPageToken,files(id,name,createdTime,description)&pageSize=1000"+(page.isEmpty()?"":"&pageToken="+java.net.URLEncoder.encode(page,"UTF-8"));JSONObject result=new JSONObject(DriveBackup.request("GET",url,token,null,null));JSONArray batch=result.getJSONArray("files");for(int i=0;i<batch.length();i++)files.put(batch.get(i));page=result.optString("nextPageToken","");}while(!page.isEmpty());return files;}
 static String download(String token,String id)throws Exception{if(!id.matches("[A-Za-z0-9_-]+"))throw new IOException();return DriveBackup.request("GET","https://www.googleapis.com/drive/v3/files/"+id+"?alt=media",token,null,null);}
}
